// Only normalize copy generated by older Metrics dashboards. Do not alter
// arbitrary descriptions or persist a migration from a read-only render.
export function metricDashboardDescription(description) {
  return description?.replace(
    /^Frozen metric run [0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\./i,
    "Saved metric result.",
  );
}
